<?php
require __DIR__.'/lib.php';require_login();$err='';
if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf();$q=db()->prepare('SELECT password_hash FROM users WHERE id=?');$q->execute([current_user()['id']]);if(!password_verify($_POST['current_password']??'',$q->fetchColumn()))throw new Exception('Current password is incorrect.');$pw=$_POST['password']??'';if(strlen($pw)<8)throw new Exception('Use at least 8 characters.');if($pw!==($_POST['confirm_password']??''))throw new Exception('New passwords do not match.');if($pw===($_POST['current_password']??''))throw new Exception('Choose a different password.');db()->prepare('UPDATE users SET password_hash=?,must_change_password=0 WHERE id=?')->execute([password_hash($pw,PASSWORD_DEFAULT),current_user()['id']]);session_regenerate_id(true);audit('Change password','User',(string)current_user()['id'],'User changed their own password.');flash('Your password was updated.');header('Location: index.php');exit;}catch(Throwable $e){$err=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><title>Change Password - RS8</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="assets/typography.css?v=5.4.6-b"></head><body class="auth-bg"><div class="auth-card"><a class="dashboard-logo" href="index.php?page=dashboard" aria-label="RS8 — Open Dashboard"><img class="auth-logo" src="assets/logos/rs8.png" alt="RS8"></a><a class="btn ghost system-back" href="index.php?page=dashboard" data-system-back aria-label="Back to previous page"><span aria-hidden="true">&#8592;</span> Back</a><h1>Change Your Password</h1><p>Use a personal password after account creation or an administrator reset.</p><?php if($err):?><div class="alert danger"><?=e($err)?></div><?php endif;?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Current Password<input name="current_password" type="password" autocomplete="current-password" required></label><label>New Password<input name="password" type="password" autocomplete="new-password" minlength="8" required></label><label>Confirm New Password<input name="confirm_password" type="password" autocomplete="new-password" minlength="8" required></label><button class="btn primary">Update My Password</button><a class="btn ghost" href="logout.php" data-confirm-logout>Sign Out</a></form></div><script>window.RS8_CSRF=<?=json_encode(csrf_token())?>;</script><script src="assets/app.js"></script></body></html>
